import base64,os,sys
b=r"e:\\Projects\\pocketmind"
def w(p,e):
 fp=os.path.join(b,p.replace("/",os.sep))
 os.makedirs(os.path.dirname(fp),exist_ok=True)
 open(fp,"w",encoding="utf-8").write(base64.b64decode(e).decode())
 sys.stderr.write("W:"+p+"\n")

w("core/build.gradle.kts","")
w("core/src/main/java/com/pocketmind/core/model/entities.kt","")
w("core/src/main/java/com/pocketmind/core/model/types.kt","")#testappend
